    @if (!empty($recaptchaSiteKey))
    <script>
        (() => {
            const form = document.getElementById('contact-form');
            const button = document.getElementById('contact-submit');
            const status = document.getElementById('captcha-status');
            const tokenInput = document.getElementById('recaptcha-token');
            const siteKey = @json($recaptchaSiteKey);
            let sending = false;

            form.addEventListener('submit', (event) => {
                if (!form.reportValidity()) return;
                event.preventDefault();
                if (sending) return;
                sending = true;
                button.disabled = true;
                button.textContent = 'Verifying…';
                status.textContent = 'Securing your request…';

                const submitWithToken = () => window.grecaptcha.execute(siteKey, { action: 'contact_submit' })
                    .then((token) => {
                        tokenInput.value = token;
                        form.submit();
                    })
                    .catch(() => {
                        sending = false;
                        button.disabled = false;
                        button.innerHTML = 'Send request <span>→</span>';
                        status.textContent = 'Verification could not load. Please check your connection and try again.';
                    });

                const waitForCaptcha = (attempts = 0) => {
                    if (window.grecaptcha && window.grecaptcha.ready) {
                        window.grecaptcha.ready(submitWithToken);
                    } else if (attempts < 40) {
                        window.setTimeout(() => waitForCaptcha(attempts + 1), 200);
                    } else {
                        sending = false;
                        button.disabled = false;
                        button.innerHTML = 'Send request <span>→</span>';
                        status.textContent = 'Verification could not load. Please check your connection and try again.';
                    }
                };
                waitForCaptcha();
            });
        })();
    </script>
    @endif
